function IPT=lms2ipt(LMS)
Mipt=[0.4000,0.4000,0.2000;4.4550,-4.8510,0.3960;0.8056,0.3572,-1.1628];
LMS=((((LMS>=0).*LMS).^0.43)-(((LMS<0).*(-LMS)).^0.43));
IPT=(Mipt*LMS')';
end